<?php
/** TEMP PS S1631 run r4 — R: eShoprent options → WP variacijų atitikimas (var_kodas=_sku; bazinis SKU+atributo reikšmė). READ-ONLY. */
add_action('init', function(){
  if (!isset($_GET['ps_s1631r4'])) return;
  $o=array('v'=>'S1631 r4'); global $wpdb; $p=$wpdb->prefix;
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $csv=gzdecode(base64_decode('')); $eil=array_filter(explode("\n",$csv));
  $sk=$wpdb->get_results("SELECT pm.meta_value sku, pm.post_id, po.post_type FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type IN('product','product_variation') AND po.post_status IN('publish','draft','private') WHERE pm.meta_key='_sku' AND pm.meta_value<>''");
  $map=array(); foreach($sk as $r){ $map[trim((string)$r->sku)]=array((int)$r->post_id,$r->post_type); }
  $norm=function($s){ $s=mb_strtolower(trim($s)); return str_replace(array('ė','ž','š','ų','ū','į','ą','č',' '),array('e','z','s','u','u','i','a','c',''),$s); };
  $a=array('kodu'=>0,'atributu'=>0,'tevas_ne_var'=>0,'tevo_nera'=>0,'reiksmes_nera'=>array()); $hits=array();
  foreach($eil as $l){ $c=explode(';',$l); list($bs,$at,$re,$vk,$q)=array($c[0],$c[1],$c[2],$c[3],(int)$c[4]);
    if($vk!=='' && isset($map[$vk]) && $map[$vk][1]==='product_variation'){ $a['kodu']++; $hits[]=$map[$vk][0]; continue; }
    if(!isset($map[$bs])){ $a['tevo_nera']++; continue; }
    $pid=$map[$bs][0];
    if($map[$bs][1]!=='product'){ $a['tevas_ne_var']++; continue; }
    $pr=wc_get_product($pid);
    if(!$pr || !$pr->is_type('variable')){ $a['tevas_ne_var']++; continue; }
    $rado=0;
    foreach($pr->get_children() as $vid){ $v=wc_get_product($vid); if(!$v) continue;
      foreach($v->get_attributes() as $tax=>$slug){ $t=get_term_by('slug',$slug,$tax); $name=$t?$t->name:$slug;
        if($norm($name)===$norm($re)){ $a['atributu']++; $hits[]=$vid; $rado=1; break 2; } } }
    if(!$rado && count($a['reiksmes_nera'])<12) $a['reiksmes_nera'][]=$bs.';'.$re.';q'.$q;
    if(!$rado) $a['reiksmes_nera_n']=($a['reiksmes_nera_n']??0)+1;
  }
  $o['atitikimas']=$a; $o['unikaliu_variaciju_pataikyta']=count(array_unique($hits));
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
